package com.clipboardfix

import android.graphics.Bitmap
import android.graphics.BitmapFactory
import java.util.Base64

/**
 * 置顶按钮图标（新版设计：浅蓝圆角方块底 + 白色上箭头字形）。
 *
 * <p>数据为新设计稿导出的 WebP（无损）base64，运行时解码。
注意：图标自带底色与字形，调用方（ClipboardPinHook.pinBtnOf）不再额外染白或叠圆形底。
 */
object PinIcon {

    // 分块存储：单个 JVM 字符串常量上限 65535 字节，整段 base64 超界会触发
    // "UTF8 string too large"，故按 30000 字符切块，运行时拼接。
    private val ICON_CHUNKS = arrayOf(
        """""",
        """"""
    )

    @Volatile
    private var cached: Bitmap? = null

    /** 取图标位图（首次调用时解码，之后走缓存）。解码失败返回 null。 */
    @JvmStatic
    fun get(): Bitmap? {
        val b = cached
        if (b != null) return b
        val b64 = buildString { for (c in ICON_CHUNKS) append(c) }
        val decoded = try {
            val raw = Base64.getDecoder().decode(b64)
            BitmapFactory.decodeByteArray(raw, 0, raw.size)
        } catch (_: Throwable) {
            null
        }
        cached = decoded
        return decoded
    }
}
